    r1 = max(r for r, _ in rect_cells)
    c0 = min(c for _, c in rect_cells)
    c1 = max(c for _, c in rect_cells)

    # Markers outside the solid 2-rectangle mark the row/column that is
    # intentionally left unextended; all other rows/columns continue to edges.
    marked_rows = set()
    marked_cols = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in (0, 2):
                if c < c0 or c > c1:
                    marked_rows.add(r)
                if r < r0 or r > r1:
                    marked_cols.add(c)

    for r in range(r0, r1 + 1):
        if r not in marked_rows:
            for c in range(w):
                out[r][c] = 2
    for c in range(c0, c1 + 1):
        if c not in marked_cols:
            for r in range(h):
                out[r][c] = 2
    return out
